// Una sola familia. Los tres tokens quedan porque los usan 80 lugares y son la
// jerarquía tipográfica de la app —logo, títulos, cuerpo— pero hoy resuelven a
// la misma fuente y el peso lo pone cada componente.
//
// `serif` conserva el nombre aunque Inter no lo sea: renombrarlo tocaría 79
// líneas de componentes, que es justo lo que este cambio no tiene que hacer.
export const F = {
  logo:  "'Inter', sans-serif",
  serif: "'Inter', sans-serif",
  body:  "'Inter', sans-serif",
};

// ─── KEYFRAME ANIMATION ──────────────────────────────────────────────────────
const styleEl = document.createElement("style");
styleEl.textContent = `
  @keyframes bvpop {
    from { opacity: 0; transform: translateY(8px); }
    to   { opacity: 1; transform: translateY(0); }
  }
  .bvpop { animation: bvpop .3s ease both; }
  * { box-sizing: border-box; }
  select, input, textarea, button { font-family: 'Inter', sans-serif; }
`;
document.head.appendChild(styleEl);
